SELECT id, store_id, last_restock, quantity, product_id, SUM(quantity) OVER (PARTITION BY store_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_quantity, LAST_VALUE(quantity) OVER (PARTITION BY store_id, product_id ORDER BY last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS last_quantity FROM inventory WHERE store_id IN (2, 3, 4, 6) ORDER BY store_id DESC;
